	}
	if !urlConfigured && viper.IsSet(dbUser) {
		cfg.Database.User = viper.GetString(dbUser)
	}
	if !urlConfigured && viper.IsSet(dbPassword) {
		cfg.Database.Password = viper.GetString(dbPassword)
	}
	if !urlConfigured && viper.IsSet(dbName) {
		cfg.Database.Name = viper.GetString(dbName)
	}
	if !urlConfigured && viper.IsSet(dbPath) {
		cfg.Database.Path = viper.GetString(dbPath)
	}
	if !urlConfigured && keyValueDatabase && !viper.IsSet(dbProtocol) {
		return nil, errors.New("db.protocol: is required when db.url is not provided")
	}

	if viper.IsSet(dbMigrationsPath) {
		cfg.Database.MigrationsPath = viper.GetString(dbMigrationsPath)
	}

	if viper.IsSet(dbMaxIdleConn) {
		cfg.Database.MaxIdleConn = viper.GetInt(dbMaxIdleConn)
	}

	if viper.IsSet(dbMaxOpenConn) {
		cfg.Database.MaxOpenConn = viper.GetInt(dbMaxOpenConn)
	}

	if viper.IsSet(dbConnMaxLifetime) {
		cfg.Database.ConnMaxLifetime = viper.GetDuration(dbConnMaxLifetime)
	}

	// Meta
	if viper.IsSet(metaCheckForUpdates) {
		cfg.Meta.CheckForUpdates = viper.GetBool(metaCheckForUpdates)
	}

	if err := cfg.validate(); err != nil {
		return &Config{}, err
	}

	return cfg, nil
}

func (c *Config) validate() error {
	if c.Server.Protocol == HTTPS {
		if c.Server.CertFile == "" {
			return errors.New("server.cert_file cannot be empty when using HTTPS")
		}

		if c.Server.CertKey == "" {
			return errors.New("server.cert_key cannot be empty when using HTTPS")
		}

		if _, err := os.Stat(c.Server.CertFile); os.IsNotExist(err) {
			return fmt.Errorf("cannot find TLS server.cert_file at %q", c.Server.CertFile)
		}

package db

import (
	"database/sql"
	"database/sql/driver"
	"fmt"
	"net/url"
	"strings"

	"github.com/go-sql-driver/mysql"
	"github.com/lib/pq"
	"github.com/luna-duclos/instrumentedsql"
	"github.com/luna-duclos/instrumentedsql/opentracing"
	"github.com/markphelps/flipt/config"
	"github.com/mattn/go-sqlite3"
	"github.com/xo/dburl"
)

// Open opens a connection to the db given a URL
func Open(cfg config.Config) (*sql.DB, Driver, error) {
	target, err := cfg.Database.ConnectionURL()
	if err != nil {
		return nil, 0, err
	}
	sql, driver, err := open(target, false)
	if err != nil {
		return nil, 0, err
	}

	configurePool(sql, cfg.Database)
	registerMetrics(driver, sql)

	return sql, driver, nil
}

func configurePool(sql *sql.DB, cfg config.DatabaseConfig) {
	sql.SetMaxIdleConns(cfg.MaxIdleConn)

	if cfg.MaxOpenConn > 0 {
		sql.SetMaxOpenConns(cfg.MaxOpenConn)
	}
	if cfg.ConnMaxLifetime > 0 {
		sql.SetConnMaxLifetime(cfg.ConnMaxLifetime)
	}
}

func open(rawurl string, migrate bool) (*sql.DB, Driver, error) {
	d, url, err := parse(rawurl, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case Postgres:
		dr = &pq.Driver{}
	case MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, url.DSN)
	if err != nil {
		return nil, 0, fmt.Errorf("opening db for driver %s: %s", d, redactConnectionError(rawurl, err))
	}

	return db, d, nil
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
		MySQL:    "mysql",
	}

	stringToDriver = map[string]Driver{
		"sqlite3":  SQLite,
		"postgres": Postgres,
		"mysql":    MySQL,
	}
)

// Driver represents a database driver
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
	// MySQL ...
	MySQL
)

func parse(rawurl string, migrate bool) (Driver, *dburl.URL, error) {
	url, err := dburl.Parse(rawurl)
	if err != nil {
		return 0, nil, fmt.Errorf("error parsing db.url: %v", redactParseError(err))
	}

	driver := stringToDriver[url.Driver]
	if driver == 0 {
		return 0, nil, fmt.Errorf("db.url: unsupported database protocol %q; expected sqlite, postgres, or mysql", url.Driver)
	}

	switch driver {
	case MySQL:
		v := url.Query()
		v.Set("multiStatements", "true")
		v.Set("parseTime", "true")
		if !migrate {
			v.Set("sql_mode", "ANSI")
		}
		url.RawQuery = v.Encode()
		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())

	case SQLite:
		v := url.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		url.RawQuery = v.Encode()

		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())
	}

	if err != nil {
		return 0, nil, fmt.Errorf("error preparing db.url: %s", redactParseError(err))
	}
	return driver, url, nil
}

// dburl parser errors can echo portions of the input. Keep parse failures useful
// without allowing credentials to appear in logs or CLI output.
func redactParseError(err error) string {
	if err == nil {
		return "invalid connection URL"
	}
	return "invalid connection URL"
}

func redactConnectionError(rawurl string, err error) string {
	message := err.Error()
	parsed, parseErr := url.Parse(rawurl)
	if parseErr == nil && parsed.User != nil {
		if password, ok := parsed.User.Password(); ok && password != "" {
			message = strings.ReplaceAll(message, password, "[redacted]")
			message = strings.ReplaceAll(message, url.QueryEscape(password), "[redacted]")
		}
	}
	return message
}
